(function(){
  function syllables(w){w=w.toLowerCase().replace(/[^a-z]/g,'');if(!w)return 0;if(w.length<=3)return 1;w=w.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/,'').replace(/^y/,'');var m=w.match(/[aeiouy]{1,2}/g);return m?m.length:1;}
  function score(text){
    if(!text||!text.trim())return{error:'请输入文本'};
    var cjk=(text.match(/[一-鿿]/g)||[]).length;
    var words=(text.match(/[A-Za-z]+/g)||[]);
    var sentences=(text.match(/[.!?。！？]+/g)||[]).length;if(sentences<1)sentences=1;
    var wcount=words.length+cjk;if(wcount<1)return{error:'未识别到词'};
    var syl=0;words.forEach(function(w){syl+=syllables(w);});
    var flesch=206.835-1.015*(wcount/sentences)-84.6*(syl/Math.max(1,wcount));
    var fk=0.39*(wcount/sentences)+11.8*(syl/Math.max(1,wcount))-15.59;
    var label=flesch>=90?'极易读':flesch>=80?'易读':flesch>=70?'较易读':flesch>=60?'标准':flesch>=50?'较难读':flesch>=30?'难读':'极难读';
    return {value:{words:wcount,sentences:sentences,syllables:syl,cjkChars:cjk,flesch:Math.round(flesch*10)/10,fkGrade:Math.round(fk*10)/10,label:label}};
  }
  var API={score:score,syllables:syllables};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__ReadabilityForge__=API;
})();
